// llm-providers.js — user-managed LLM providers for the Models page.
//
// The env-driven Volces route is generated by dsh-profile.js (buildLlmProfile).
// This module owns the *user-added* providers: they persist to a JSON file under
// PLATFORM_DATA_DIR (llm-providers.json) and are merged into the dsh
// `llm-pi-ai:` settings section + .credentials.yaml whenever writeLlmProfile()
// runs. Because dsh-settings-file and dsh-credentials-local both hot-reload
// those files, a provider add/edit/delete takes effect live — no dsh restart
// (the same hot-reload path /api/models/refresh already relies on).
//
// Security: the raw API key is written only to .credentials.yaml (0600) and
// referenced by env-var name in settings.yaml. The client-facing record carries
// `hasKey: boolean` only — the key is never returned, logged, or echoed.
//
// Provider ids are stable, url-safe slugs derived from the display name
// (collisions get a numeric suffix). The Volces route id ("volces") is reserved
// and cannot be added/edited/deleted through this module.

import { storeDir } from "./paths.js";
import { readJsonOr, atomicWriteJsonSync, createWriteChain, normalizeBaseUrl } from "./lib/persistence.js";
// RETRY_POLICY is the single resilience source (add-llm-retry-resilience):
// user routes carry the same bounded transient-error retry as the env route.
// This edge is safe against the module cycle this header guards against —
// dsh-profile imports THIS module only lazily (inside buildLlmProfile), so
// however the load order starts, the other side is never mid-evaluation.
import { RETRY_POLICY } from "./dsh-profile.js";
// 词元能力快照消费侧（add-ciyuan-capability-contract）：快照只缩小「要探哪些 id」，
// 不替代判定——探到才算 serving。读不到（404/503/超时/形状不符）就退回 /models
// 全量探测，行为不比现状更差。
import {
  capabilitiesDiscoveryEnabled,
  fetchCapabilities,
  planProbeSet,
} from "./lib/ciyuan-capabilities.js";

const STORE_PATH = storeDir("llm-providers.json", process.env.LLM_PROVIDERS_STORE);
const DEFAULT_PATH = storeDir("llm-default.json", process.env.LLM_DEFAULT_STORE);

// Provider ids reserved for the env-generated routes (cannot be user-managed).
export const RESERVED_IDS = new Set(["volces"]);

// Per-provider model declaration. User providers are OpenAI-compatible; we
// can't discover models until the route is live, so we declare a small set of
// well-known ids the selector can offer immediately. The real discovered list
// arrives later via dsh-llm's discoverModels() (out of scope for the CRUD path).
const DEFAULT_MODELS = [
  { id: "deepseek-v4-pro", name: "DeepSeek V4 Pro", contextWindow: 1_000_000, maxTokens: 8192 },
];

// ── Model family metadata (add-llm-model-discovery, design D5) ───────────────
//
// The gateway publishes no metadata, so verified-per-family defaults live here
// (2026-09-30 probe session). Sync merges ids with these values; entries the
// operator already hand-tuned are never rewritten. `rank` drives post-sync
// ordering: deepseek → glm → mimo → rest → `:free` last — the dropdown keeps
// the agreed shape regardless of gateway listing order.

const IDENTITY_EFFORTS = ["low", "medium", "high"];

export const MODEL_FAMILY_DEFAULTS = Object.freeze({
  contextWindow: 128000,
  maxTokens: 8192,
  reasoningEfforts: [], // no thinking control
});

// Ordered by specificity: first prefix hit wins. Prefixes match the id after
// its final "/" (the gateway mixes bare `deepseek-v4.1-flash` with
// OpenRouter-style `deepseek/deepseek-v4.1-flash`; both are the same family).
// Efforts are scoped to the verified deepseek-v4 lane only (same rule as
// dsh-profile's declaredEfforts: a wrong `false` hides a control, a wrong map
// is a dispatch error).
const MODEL_FAMILIES = [
  // 词元 deepseek-v4 车道的窗口是**实测**的 1M（2026-11-11：prompt=1,000,038 → 200/stop；
  // 更大时先撞 8MB 请求体上限）。声明 128k 会把 dsh/pi-ai 的输出预算压成个位数——
  // 线上就是 720 个 MCP 工具（≈15.9 万 token）> 12.8 万 → 每回合只剩 128 个 token。
  { prefix: "deepseek-v4", rank: 0, maxTokens: 32768, contextWindow: 1_000_000, reasoningEfforts: IDENTITY_EFFORTS },
  { prefix: "deepseek", rank: 0, maxTokens: 32768 },
  { prefix: "glm-5.3-flash", rank: 1, maxTokens: 32768 },
  { prefix: "glm", rank: 1 },
  { prefix: "mimo", rank: 2 },
];

function familyFor(id) {
  const bare = String(id).split("/").pop();
  return MODEL_FAMILIES.find((f) => bare.startsWith(f.prefix)) || null;
}

// Metadata for a model id: family-table values with conservative fallbacks.
export function modelFamilyMeta(id) {
  const f = familyFor(id);
  return {
    contextWindow: f?.contextWindow ?? MODEL_FAMILY_DEFAULTS.contextWindow,
    maxTokens: f?.maxTokens ?? MODEL_FAMILY_DEFAULTS.maxTokens,
    reasoningEfforts: [...(f?.reasoningEfforts ?? MODEL_FAMILY_DEFAULTS.reasoningEfforts)],
  };
}

// ── Resolving a roster entry's metadata (conservative default = "untuned") ───
//
// A value equal to the conservative default is what normalizeModelsInput writes
// when the caller supplied nothing, so on its own it carries no intent. On a
// family that publishes a verified window it is also the exact shape of the
// 2026-10 incident: 720 MCP tools ≈ 159k tokens against a declared 128k, so
// `available = contextWindow − 估算 − 4096` went negative and every turn was
// left ~128 output tokens — ending as stopReason=length with nothing in the log
// saying why (1,467 `context overflow` rows in /data/meter.jsonl).
//
// Resolution therefore treats the conservative default as "untuned" and prefers
// the family value, unless the operator pinned one (`metaPinned`, written by the
// editor when the supplied value disagrees with the family table). The failure
// this trades into is the loud one: pi-ai reports `context overflow`.
//
// Read at every resolution site (dsh route declarations, served model list,
// panel roster, sync persistence) so a stale store — an older volume, a node
// that never synced, a roster written before this rule — cannot squeeze the
// runtime's output budget. Data repair is not a precondition.
export function effectiveModelMeta(entry) {
  const meta = modelFamilyMeta(entry?.id);
  const stored = (v) => (Number.isInteger(v) && v > 0 ? v : null);
  const storedCw = stored(entry?.contextWindow);
  const storedMt = stored(entry?.maxTokens);
  if (entry?.metaPinned) {
    return { contextWindow: storedCw ?? meta.contextWindow, maxTokens: storedMt ?? meta.maxTokens };
  }
  return {
    contextWindow:
      storedCw === null || storedCw === MODEL_FAMILY_DEFAULTS.contextWindow ? meta.contextWindow : storedCw,
    maxTokens: storedMt === null || storedMt === MODEL_FAMILY_DEFAULTS.maxTokens ? meta.maxTokens : storedMt,
  };
}

// The fields sync would have to rewrite for `entry` (null = already resolved).
export function reconcileModelMeta(entry) {
  const want = effectiveModelMeta(entry);
  const patch = {};
  if (entry?.contextWindow !== want.contextWindow) patch.contextWindow = want.contextWindow;
  if (entry?.maxTokens !== want.maxTokens) patch.maxTokens = want.maxTokens;
  return Object.keys(patch).length ? patch : null;
}

// Ordering rank: `:free` ids are always last (free pool), else the family's
// rank, else 3 ("rest").
export function modelFamilyRank(id) {
  if (String(id).endsWith(":free")) return 4;
  return familyFor(id)?.rank ?? 3;
}

function compareModelIds(a, b) {
  return modelFamilyRank(a) - modelFamilyRank(b) || String(a).localeCompare(String(b));
}

// Display name for a synced id (`deepseek-v4.1-flash` → `DeepSeek V4.1 Flash`).
// Dots stay inside a token (version numbers); the few known brand spellings
// are cased by hand.
const BRAND_SPELLINGS = { deepseek: "DeepSeek", glm: "GLM", mimo: "MiMo", kimi: "Kimi" };
function prettifyModelId(id) {
  return String(id)
    .split(/[/]+/).pop()
    .split(/[-_]+/)
    .filter(Boolean)
    .map((tok) => BRAND_SPELLINGS[tok.toLowerCase()] ?? tok.charAt(0).toUpperCase() + tok.slice(1))
    .join(" ");
}

// ── Storage ──────────────────────────────────────────────────────────────────

// All mutations run through this chain's non-blocking variant: a second
// concurrent edit is rejected with BusyError (code "busy") rather than
// queued, which the REST layer maps to 409 (llm-model-management contract).
// The chain lives here, next to the data it protects (the REST routes call
// tryWithWriteLock; they no longer own the mutex).
const writeChain = createWriteChain();

export function tryWithWriteLock(fn) {
  return writeChain.tryMutate(fn);
}

function readJson(path, fallback) {
  return readJsonOr(path, fallback, { label: "llm-providers" });
}

function writeJsonAtomic(path, value) {
  atomicWriteJsonSync(path, value);
}

function readProvidersDoc() {
  const doc = readJson(STORE_PATH, { providers: [] });
  return Array.isArray(doc.providers) ? doc : { providers: [] };
}

// ── Reserved-route override (add-editable-llm-route, design D1) ─────────────
// The env-generated volces route stays reserved (no user row, key stays in
// env), but its roster and base URL gain a persisted operator override:
// resolution is override > env > baked-in code constant, and clearing the
// override restores the seed projection (the rollback path). The override is
// a sibling key of `providers` in the same store file — one write chain, one
// lock — and survives user-provider mutations because every writer round-trips
// the whole doc.

export function getVolcesOverride() {
  const ov = readProvidersDoc().volcesOverride;
  if (!ov || typeof ov !== "object") return null;
  const out = {};
  if (ov.baseUrl && String(ov.baseUrl).trim()) out.baseUrl = ov.baseUrl;
  if (Array.isArray(ov.models)) out.models = ov.models;
  if (ov.discovery && typeof ov.discovery === "object") out.discovery = ov.discovery;
  if (ov.updatedAt) out.updatedAt = ov.updatedAt;
  return Object.keys(out).length ? out : null;
}

// Merge-shaped write: only the keys present in `patch` change; the rest keep
// their current values. `null`/"" clears a field. `models` must already be
// normalized (normalizeModelsInput) — callers validate before writing.
export function setVolcesOverride(patch) {
  const doc = readProvidersDoc();
  const current = doc.volcesOverride || {};
  // baseUrl normalizes at the store boundary (adds /v1 to a pathless origin)
  // so every reader — the route's override indicator included — sees the
  // canonical form regardless of which writer set it.
  const normalizeUrl = (v) => (v && String(v).trim() ? normalizeBaseUrl(String(v).trim()) : undefined);
  const next = {
    baseUrl: "baseUrl" in patch ? normalizeUrl(patch.baseUrl) : current.baseUrl,
    models: "models" in patch ? patch.models : current.models,
    discovery: "discovery" in patch ? patch.discovery : current.discovery,
    updatedAt: new Date().toISOString(),
  };
  doc.volcesOverride = next;
  writeJsonAtomic(STORE_PATH, doc);
  return getVolcesOverride();
}

export function clearVolcesOverride() {
  const doc = readProvidersDoc();
  if (!doc.volcesOverride) return false;
  delete doc.volcesOverride;
  writeJsonAtomic(STORE_PATH, doc);
  return true;
}

// ── Slug / id helpers ────────────────────────────────────────────────────────

function slugify(name) {
  return String(name || "")
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40) || "provider";
}

function uniqueId(name, existing) {
  const base = slugify(name);
  if (!existing.has(base) && !RESERVED_IDS.has(base)) return base;
  let i = 2;
  while (existing.has(`${base}-${i}`) || RESERVED_IDS.has(`${base}-${i}`)) i += 1;
  return `${base}-${i}`;
}

// ── Validation ───────────────────────────────────────────────────────────────

export class ProviderError extends Error {
  constructor(code, message) {
    super(message);
    this.code = code; // "invalid" | "not_found" | "duplicate" | "only_provider"
  }
}

const URL_RE = /^https?:\/\/[^\s]+$/i;

function validateInput({ name, baseUrl, apiKey, reasoningEfforts, auth }, { requireKey }) {
  const errors = [];
  const cleanName = String(name || "").trim();
  if (cleanName.length < 1) errors.push("name is required");
  if (cleanName.length > 60) errors.push("name must be 60 characters or fewer");
  if (!URL_RE.test(String(baseUrl || "").trim())) errors.push("baseUrl must be a valid http(s) URL");
  // Auth form (add-local-model-lane): "bearer" (default) needs a key;
  // "none" (local model servers) may omit it entirely.
  const cleanAuth = auth === undefined || auth === null || auth === "" ? "bearer" : String(auth);
  if (cleanAuth !== "bearer" && cleanAuth !== "none") errors.push('auth must be "bearer" or "none"');
  if (requireKey && cleanAuth === "bearer" && !String(apiKey || "").trim()) errors.push("apiKey is required");
  // Optional thinking levels: accepted verbatim (identity wire values). We only
  // reject shapes we cannot write, not level names — the operator knows their
  // gateway better than we do.
  const levels = normalizeEfforts(reasoningEfforts);
  if (levels === null) errors.push("reasoningEfforts must be a list of level names");
  if (errors.length) throw new ProviderError("invalid", errors.join("; "));
  return {
    name: cleanName,
    baseUrl: normalizeBaseUrl(String(baseUrl).trim()),
    apiKey: String(apiKey || "").trim(),
    reasoningEfforts: levels,
    auth: cleanAuth,
  };
}

// Accept an array or a comma-separated string; [] when unset. null = invalid.
function normalizeEfforts(value) {
  if (value === undefined || value === null || value === "") return [];
  const raw = Array.isArray(value) ? value : String(value).split(",");
  if (!raw.every((v) => typeof v === "string" || typeof v === "number")) return null;
  return [...new Set(raw.map((v) => String(v).trim()).filter(Boolean))];
}

// ── Public CRUD (returns the persisted, client-safe record) ──────────────────

// List user providers. `hasKey` reflects whether a credential is stored.
// `discovery` is the last sync's per-id status map (null before any sync).
// Delegates to clientRecord: this used to be a hand-copied duplicate of that
// shape, so a field added to one never reached the other (modelMeta was added
// to clientRecord and the panel still got nothing).
export function listUserProviders() {
  return readProvidersDoc().providers.map(clientRecord);
}

// Raw record (includes apiKey) — internal/server use (route credentials,
// llm-guard probes). The client surface is clientRecord/listUserProviders.
export function getProviderRecord(id) {
  return readProvidersDoc().providers.find((p) => p.id === id) || null;
}

export function createProvider(input) {
  const clean = validateInput(input, { requireKey: true });
  const { name, baseUrl, apiKey, reasoningEfforts } = clean;
  const doc = readProvidersDoc();
  const existing = new Set(doc.providers.map((p) => p.id));
  if (doc.providers.some((p) => p.name.toLowerCase() === name.toLowerCase())) {
    throw new ProviderError("duplicate", `a provider named "${name}" already exists`);
  }
  const id = uniqueId(name, existing);
  const record = {
    id,
    name,
    baseUrl,
    apiKey,
    auth: clean.auth,
    type: "openai-completions",
    models: DEFAULT_MODELS,
    reasoningEfforts,
    createdAt: new Date().toISOString(),
    lastTest: null,
  };
  doc.providers.push(record);
  writeJsonAtomic(STORE_PATH, doc);
  console.log(`[llm-providers] added "${name}" (${id})`);
  return clientRecord(record);
}

export function updateProvider(id, input) {
  if (RESERVED_IDS.has(id)) return updateVolcesOverrideInput(input);
  const doc = readProvidersDoc();
  const idx = doc.providers.findIndex((p) => p.id === id);
  if (idx < 0) throw new ProviderError("not_found", `provider ${id} not found`);
  const current = doc.providers[idx];

  // Partial update: omitted fields keep current values. An EMPTY apiKey means
  // "keep current" (per design D6); a non-empty value replaces it.
  const merged = {
    name: input.name !== undefined ? input.name : current.name,
    baseUrl: input.baseUrl !== undefined ? input.baseUrl : current.baseUrl,
    apiKey: input.apiKey && String(input.apiKey).trim() ? String(input.apiKey).trim() : current.apiKey,
    reasoningEfforts:
      input.reasoningEfforts !== undefined ? input.reasoningEfforts : current.reasoningEfforts,
    auth: input.auth !== undefined ? input.auth : current.auth,
  };
  const clean = validateInput(merged, { requireKey: (merged.auth ?? "bearer") === "bearer" });

  // A `models` array replaces the whole roster (add-llm-model-discovery):
  // ids must be unique non-empty strings; absent per-entry fields fall back
  // to the family table, then conservative defaults.
  const models = input.models !== undefined ? normalizeModelsInput(input.models) : current.models;

  // Uniqueness against siblings.
  if (
    doc.providers.some(
      (p) => p.id !== id && p.name.toLowerCase() === clean.name.toLowerCase(),
    )
  ) {
    throw new ProviderError("duplicate", `a provider named "${clean.name}" already exists`);
  }

  doc.providers[idx] = {
    ...current,
    name: clean.name,
    baseUrl: clean.baseUrl,
    apiKey: clean.apiKey,
    auth: clean.auth,
    reasoningEfforts: clean.reasoningEfforts,
    ...(models !== undefined ? { models } : {}),
    updatedAt: new Date().toISOString(),
  };
  writeJsonAtomic(STORE_PATH, doc);
  console.log(`[llm-providers] updated "${clean.name}" (${id})`);
  return clientRecord(doc.providers[idx]);
}

// Validate + fill a replacement roster. Invalid shapes throw `invalid` with
// the offending entry named, leaving the stored roster untouched.
function normalizeModelsInput(models) {
  if (!Array.isArray(models)) throw new ProviderError("invalid", "models must be an array");
  const seen = new Set();
  return models.map((entry) => {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
      throw new ProviderError("invalid", "each model entry must be an object");
    }
    const id = String(entry.id || "").trim();
    if (!id) throw new ProviderError("invalid", "model id is required");
    if (seen.has(id)) throw new ProviderError("invalid", `duplicate model id: ${id}`);
    seen.add(id);
    const meta = modelFamilyMeta(id);
    const positiveInt = (v, field) => {
      if (v === undefined || v === null || v === "") return null;
      const n = Number(v);
      if (!Number.isInteger(n) || n <= 0) {
        throw new ProviderError("invalid", `${field} must be a positive integer`);
      }
      return n;
    };
    const suppliedCw = positiveInt(entry.contextWindow, "contextWindow");
    const suppliedMt = positiveInt(entry.maxTokens, "maxTokens");
    const contextWindow = suppliedCw ?? meta.contextWindow;
    const maxTokens = suppliedMt ?? meta.maxTokens;
    // A pin is "the operator's number disagrees with the family table". A
    // round-tripped family value is NOT a pin — otherwise the panel's own save
    // would freeze every entry and the family-table correction could never
    // reach a roster again (that freeze is what this rule exists to undo).
    const metaPinned =
      (suppliedCw !== null && suppliedCw !== meta.contextWindow) ||
      (suppliedMt !== null && suppliedMt !== meta.maxTokens);
    const name =
      entry.name !== undefined && String(entry.name).trim()
        ? String(entry.name).trim()
        : prettifyModelId(id);
    let levels = [...meta.reasoningEfforts];
    if (entry.reasoningEfforts !== undefined && entry.reasoningEfforts !== null && entry.reasoningEfforts !== "") {
      const explicit = normalizeEfforts(entry.reasoningEfforts);
      if (explicit === null) throw new ProviderError("invalid", "reasoningEfforts must be a list of level names");
      levels = explicit;
    }
    return {
      id,
      name,
      contextWindow,
      maxTokens,
      ...(metaPinned ? { metaPinned: true } : {}),
      ...(levels.length ? { reasoningEfforts: levels } : {}),
    };
  });
}

// The reserved route accepts exactly { baseUrl?, models? } (design D3): the
// roster and base URL become operator-owned through the override; everything
// else — name, type, and above all apiKey — stays env-owned. Deletion is
// deleteProvider's reserved guard, unchanged.
function updateVolcesOverrideInput(input) {
  const patch = input || {};
  for (const key of Object.keys(patch)) {
    if (key !== "baseUrl" && key !== "models") {
      throw new ProviderError(
        "invalid",
        `reserved route field "${key}" is not editable (baseUrl and models only; the API key is env-owned)`
      );
    }
  }
  const next = {};
  if (patch.baseUrl !== undefined) {
    const raw = String(patch.baseUrl).trim();
    if (!raw) throw new ProviderError("invalid", "baseUrl cannot be empty (use override clear to reset)");
    next.baseUrl = normalizeBaseUrl(raw);
  }
  if (patch.models !== undefined) next.models = normalizeModelsInput(patch.models);
  if (!Object.keys(next).length) {
    throw new ProviderError("invalid", "nothing to update: baseUrl or models required");
  }
  const override = setVolcesOverride(next);
  console.log(`[llm-providers] volces override updated (${Object.keys(next).join(", ")})`);
  return { id: "volces", reserved: true, override };
}

export function deleteProvider(id) {
  if (RESERVED_IDS.has(id)) throw new ProviderError("invalid", "reserved provider id");
  const doc = readProvidersDoc();
  const idx = doc.providers.findIndex((p) => p.id === id);
  if (idx < 0) throw new ProviderError("not_found", `provider ${id} not found`);
  // Keep at least one provider overall: env Volces (if present) counts.
  const envCount = process.env.LLM_API_KEY?.trim() ? 1 : 0;
  if (doc.providers.length + envCount <= 1) {
    throw new ProviderError("only_provider", "cannot delete the only configured provider");
  }
  const [removed] = doc.providers.splice(idx, 1);
  writeJsonAtomic(STORE_PATH, doc);
  console.log(`[llm-providers] deleted "${removed.name}" (${id})`);
}

function clientRecord(p) {
  const roster = p.models || DEFAULT_MODELS;
  // `models` stays an id list (client pickers key on it), but the editor needs
  // the numbers the runtime actually resolves — otherwise it prefills from its
  // own family mirror, saves, and silently overwrites an operator's pinned
  // window (or reintroduces the conservative default this change removes).
  const modelMeta = {};
  for (const m of roster) {
    const meta = effectiveModelMeta(m);
    modelMeta[m.id] = { ...meta, ...(m.metaPinned ? { pinned: true } : {}) };
  }
  return {
    id: p.id,
    name: p.name,
    baseUrl: p.baseUrl,
    type: "openai-completions",
    auth: p.auth === "none" ? "none" : "bearer",
    hasKey: Boolean(p.apiKey),
    models: roster.map((m) => m.id),
    modelMeta,
    reasoningEfforts: p.reasoningEfforts || [],
    lastTest: p.lastTest || null,
    discovery: p.discovery || null,
  };
}

// ── Merge into the dsh profile (called by dsh-profile.writeLlmProfile) ────────
//
// Returns the additional providers dict + flat model list for the user-managed
// routes. The apiKey is mapped to a synthetic env-var name (LLM_PROVIDER_KEY_<ID>)
// whose value is written to .credentials.yaml by credentialRefsForUserProviders();
// settings.yaml stores only the env name, never the literal key.

const ENV_NAME_RE = /[^A-Z0-9]/g;
export function envRefForProvider(id) {
  return `LLM_PROVIDER_KEY_${String(id).toUpperCase().replace(ENV_NAME_RE, "_")}`;
}

// Build the llm-pi-ai providers entries for user routes. Each route references
// its key by env name (resolved from .credentials.yaml by dsh-credentials-local).
export function buildUserProviderEntries() {
  const providers = {};
  const models = [];
  for (const p of readProvidersDoc().providers) {
    // Identity wire values: the operator's level names are sent verbatim.
    // Per-model levels (family table via sync, or an explicit editor value)
    // win over the provider-level default.
    const routeModels = (p.models || DEFAULT_MODELS).map((m) => {
      const levels =
        Array.isArray(m.reasoningEfforts) && m.reasoningEfforts.length
          ? m.reasoningEfforts
          : p.reasoningEfforts || [];
      const effortMap = levels.length ? Object.fromEntries(levels.map((l) => [l, l])) : false;
      // The numbers dsh meters against come from the resolver, not straight
      // from the store: a stale conservative default would otherwise declare a
      // 128k window for a 1M lane and leave every turn ~128 output tokens.
      const { contextWindow, maxTokens } = effectiveModelMeta(m);
      return {
        id: m.id,
        name: m.name || prettifyModelId(m.id),
        contextWindow,
        maxTokens,
        input: ["text"],
        reasoningEfforts: effortMap,
      };
    });
    providers[p.id] = {
      retryPolicy: { ...RETRY_POLICY, backoff: { ...RETRY_POLICY.backoff } },
      apiKeyEnv: envRefForProvider(p.id),
      displayName: p.name,
      api: "openai-completions",
      baseURL: p.baseUrl,
      models: routeModels,
    };
    for (const m of routeModels) {
      const levels = effortLevelsOf(m);
      models.push({
        id: m.id,
        name: m.name,
        provider: p.id,
        ...(levels.length ? { reasoningEfforts: levels } : {}),
        // getAvailableModels() and the chat context meter divide by this. The
        // env route always carried it; the user routes never did, so their
        // models silently had no denominator (chat-usage-display).
        ...(typeof m.contextWindow === "number" ? { contextWindow: m.contextWindow } : {}),
      });
    }
  }
  return { providers, models };
}

function effortLevelsOf(model) {
  return model.reasoningEfforts && typeof model.reasoningEfforts === "object"
    ? Object.keys(model.reasoningEfforts)
    : [];
}

// The {refName: value} pairs to seed into .credentials.yaml so the per-provider
// env refs resolve. Keyless providers (add-local-model-lane, auth "none") are
// seeded with an EMPTY value: the route's env ref stays resolvable for dsh, but
// no key material exists to leak. Only providers with a key would have been
// excluded before this.
export function credentialRefsForUserProviders() {
  const refs = {};
  for (const p of readProvidersDoc().providers) {
    // Keyless lane: an EMPTY value keeps the env ref resolvable without any
    // key material. Auth-less records (pre-lane) count as bearer → skipped.
    if (p.auth === "none") refs[envRefForProvider(p.id)] = "";
    else if (p.apiKey) refs[envRefForProvider(p.id)] = p.apiKey;
  }
  return refs;
}

// ── Default model pointer ────────────────────────────────────────────────────

export function getDefault() {
  const doc = readJson(DEFAULT_PATH, null);
  if (doc && typeof doc === "object" && doc.modelId) {
    return { providerId: doc.providerId || null, modelId: doc.modelId };
  }
  return { providerId: null, modelId: null };
}

export function setDefault({ providerId, modelId }) {
  if (!modelId || typeof modelId !== "string") {
    throw new ProviderError("invalid", "modelId is required");
  }
  const doc = { providerId: providerId || null, modelId, updatedAt: new Date().toISOString() };
  writeJsonAtomic(DEFAULT_PATH, doc);
  return { providerId: doc.providerId, modelId: doc.modelId };
}

// ── Connection test (lightweight GET <baseUrl>/models) ───────────────────────

// Strip anything that looks like a bearer token / the configured key from error
// strings, and cap the body so a huge error page never reaches the UI/logs.
function sanitizeError(text, key) {
  let s = String(text || "").replace(/\s+/g, " ").trim();
  if (key) s = s.split(key).join("***");
  s = s.replace(/Bearer\s+[A-Za-z0-9._\-]+/gi, "Bearer ***");
  return s.slice(0, 200);
}

// Probe the provider. Returns { ok, latencyMs, error? }. `key` is passed in by
// the caller (server.js) from the persisted record; it is never logged.
export async function testProvider(id, { fetchImpl = global.fetch } = {}) {
  const record = getProviderRecord(id);
  if (!record) throw new ProviderError("not_found", `provider ${id} not found`);
  // The local model lane (add-local-model-lane): auth "none" providers (Ollama,
  // LM Studio) carry no key — the probe simply goes out WITHOUT Authorization
  // instead of refusing.
  const keyless = record.auth === "none";
  if (!record.apiKey && !keyless) throw new ProviderError("invalid", "provider has no API key configured");

  const probeUrl = record.baseUrl.replace(/\/+$/, "") + "/models";
  const start = Date.now();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 5000);
  try {
    const res = await fetchImpl(probeUrl, {
      method: "GET",
      headers: keyless
        ? { Accept: "application/json" }
        : { Authorization: `Bearer ${record.apiKey}`, Accept: "application/json" },
      signal: controller.signal,
    });
    const latencyMs = Date.now() - start;
    if (!res.ok) {
      let body = "";
      try { body = await res.text(); } catch { /* ignore */ }
      const error = sanitizeError(`HTTP ${res.status}: ${body}`, record.apiKey);
      await persistTestResult(id, { ok: false, latencyMs, error, at: new Date().toISOString() });
      return { ok: false, latencyMs, error };
    }
    await persistTestResult(id, { ok: true, latencyMs, at: new Date().toISOString() });
    return { ok: true, latencyMs };
  } catch (err) {
    const latencyMs = Date.now() - start;
    const msg = err?.name === "AbortError" ? "timeout after 5s" : err?.message || "request failed";
    const error = sanitizeError(msg, record.apiKey);
    await persistTestResult(id, { ok: false, latencyMs, error, at: new Date().toISOString() }).catch(() => {});
    return { ok: false, latencyMs, error };
  } finally {
    clearTimeout(timer);
  }
}

async function persistTestResult(id, lastTest) {
  const doc = readProvidersDoc();
  const idx = doc.providers.findIndex((p) => p.id === id);
  if (idx < 0) return;
  doc.providers[idx].lastTest = lastTest;
  writeJsonAtomic(STORE_PATH, doc);
}

// ── Model discovery: fetch + probe + classify + merge (add-llm-model-discovery) ──

// Gateway error substrings → status (2026-09-30 probe session, design D2).
// Text matching is on lowercased, whitespace-collapsed bodies; the exact
// gateway strings live here, one place to update when the gateway rewords.
const ERROR_MATCHERS = [
  // "Model X is not supported by any configured account in this group" (404/400)
  { status: "unauthorized", substrings: ["not supported by any configured account"] },
  // "Service temporarily unavailable" / "Upstream service temporarily unavailable" (503)
  { status: "upstream_down", substrings: ["service temporarily unavailable"] },
  // "Rate limit exceeded..." (429)
  { status: "rate_limited", substrings: ["rate limit"] },
];

const PROBE_CONCURRENCY = 4;
const PROBE_TIMEOUT_MS = 30_000;

function normalizeText(s) {
  return String(s || "").replace(/\s+/g, " ").trim().toLowerCase();
}

// Fetch the full id list from GET <baseUrl>/models. The gateway treats this as
// "recognized ids", not "serving ids" — that is exactly why sync probes.
async function fetchModelIds(baseUrl, apiKey, { fetchImpl = global.fetch, auth = "bearer" } = {}) {
  const url = String(baseUrl).replace(/\/+$/, "") + "/models";
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), PROBE_TIMEOUT_MS);
  try {
    const res = await fetchImpl(url, {
      method: "GET",
      headers:
        auth === "none"
          ? { Accept: "application/json" }
          : { Authorization: `Bearer ${apiKey}`, Accept: "application/json" },
      signal: controller.signal,
    });
    if (!res.ok) {
      let body = "";
      try { body = await res.text(); } catch { /* ignore */ }
      throw new ProviderError("invalid", sanitizeError(`model list unavailable — HTTP ${res.status}: ${body}`, apiKey));
    }
    const doc = await res.json();
    const ids = Array.isArray(doc?.data)
      ? doc.data.map((m) => m?.id).filter((id) => typeof id === "string" && id.trim())
      : [];
    return [...new Set(ids)];
  } catch (err) {
    if (err instanceof ProviderError) throw err;
    const msg = err?.name === "AbortError" ? "model list request timed out" : err?.message || "request failed";
    throw new ProviderError("invalid", sanitizeError(msg, apiKey));
  } finally {
    clearTimeout(timer);
  }
}

// Classify one probe response per design D2: HTTP shape first, then
// error-text matchers. Returns { status, error? }.
// Shared with server/llm-guard.js (the default-lane probe classifies with the
// same taxonomy as sync so "dark" means the same thing everywhere).
export function classifyResponse(status, body, apiKey) {
  if (status >= 200 && status < 300) {
    let data = null;
    try { data = JSON.parse(body); } catch { /* fall through */ }
    const choice = Array.isArray(data?.choices) ? data.choices[0] : null;
    const content = choice?.message?.content;
    const usable =
      (typeof content === "string" && content.trim()) ||
      (Array.isArray(content) && content.some((p) => typeof p?.text === "string" && p.text.trim()));
    if (choice && usable) return { status: "serving" };
    // 200 with empty/whitespace content (or no choices at all): the id answers
    // but produces no usable assistant reply — a classifier lane.
    return { status: "not_chat" };
  }
  const normalized = normalizeText(`HTTP ${status}: ${body}`);
  for (const matcher of ERROR_MATCHERS) {
    if (matcher.substrings.some((s) => normalized.includes(s))) return { status: matcher.status };
  }
  if (status === 429) return { status: "rate_limited" };
  return { status: "error", error: sanitizeError(`HTTP ${status}: ${body}`, apiKey) };
}

// Probe one id with a single minimal chat completion (design D1: the list
// endpoint cannot distinguish serving from recognized). One retry for
// rate_limited / network failures only (D3).
async function probeModel(baseUrl, apiKey, id, { fetchImpl, timeoutMs, auth = "bearer" }) {
  const url = String(baseUrl).replace(/\/+$/, "") + "/chat/completions";
  const attempt = async () => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const res = await fetchImpl(url, {
        method: "POST",
        headers: {
          ...(auth === "none" ? {} : { Authorization: `Bearer ${apiKey}` }),
          "Content-Type": "application/json",
          Accept: "application/json",
        },
        body: JSON.stringify({
          model: id,
          messages: [{ role: "user", content: "只回复ok" }],
          max_tokens: 1,
          stream: false,
        }),
        signal: controller.signal,
      });
      let body = "";
      try { body = await res.text(); } catch { /* ignore */ }
      return classifyResponse(res.status, body, apiKey);
    } catch (err) {
      const msg = err?.name === "AbortError" ? `probe timed out after ${timeoutMs / 1000}s` : err?.message || "request failed";
      return { status: "network_error", error: sanitizeError(msg, apiKey) };
    } finally {
      clearTimeout(timer);
    }
  };

  const first = await attempt();
  if (first.status !== "network_error" && first.status !== "rate_limited") return first;
  const second = await attempt();
  if (second.status === "network_error") {
    // The retry failed on the network too: a persistent network failure is a
    // plain error; an original rate_limited signal wins over the retry noise.
    return first.status === "rate_limited"
      ? { status: "rate_limited" }
      : { status: "error", error: second.error };
  }
  return second;
}

// Classify every id: bounded-concurrency probes (4), per-probe 30s timeout.
// Returns { [id]: { status, error? } } covering every id.
export async function classifyModels(baseUrl, apiKey, ids, { fetchImpl = global.fetch, timeoutMs = PROBE_TIMEOUT_MS, auth = "bearer" } = {}) {
  const results = {};
  const queue = [...ids];
  const workers = Array.from({ length: Math.min(PROBE_CONCURRENCY, Math.max(1, ids.length)) }, async () => {
    for (;;) {
      const id = queue.shift();
      if (id === undefined) return;
      results[id] = await probeModel(baseUrl, apiKey, id, { fetchImpl, timeoutMs, auth });
    }
  });
  await Promise.all(workers);
  return results;
}

// One sync at a time across all providers (spec: a second sync while any sync
// runs is a 409). Covers the classification phase, which runs outside the
// write lock; the merge itself additionally goes through tryWithWriteLock.
let syncInFlight = false;

// Decide which ids a sync should probe.
//
// 词元（ciyuan）能力快照优先：`GET /v1/ciyuan/capabilities` 按调用者的 key 给出
// serving（可调度账号映射并集）与 permitted_only（看得见但没有账号能服务）。
// 后者今天在 /models 里也列出来、探一次必然 unauthorized——纯白探。
//
// 纪律（契约 ciyuan-capability-endpoint）：快照**只缩小探测集合，不替代判定**。
// 探到才算 serving，所以快照任何错误只会让集合保守：
//  - 快照不可用 → 退回 /models 全量探测（与启用本机制前完全一致）
//  - serving 空但有 permitted_only → 仍探这些（账号可能刚上线，快照未刷新）
//  - serving 非空 → 只探 serving，跳过 permitted_only（记入 skipped 供日志归因）
async function planSyncProbeSet(baseUrl, apiKey, { fetchImpl, auth = "bearer" } = {}) {
  const fallback = async () => ({
    ids: await fetchModelIds(baseUrl, apiKey, { fetchImpl, auth }),
    source: "models",
    snapshotServing: null,
    skipped: [],
  });
  if (!capabilitiesDiscoveryEnabled()) return fallback();

  const snapshot = await fetchCapabilities(baseUrl, apiKey, { fetchImpl, auth });
  if (!snapshot) return fallback();

  const plan = planProbeSet(snapshot, []);
  if (plan.source !== "capabilities" || plan.ids.length === 0) return fallback();
  return {
    ids: plan.ids,
    source: "capabilities",
    snapshotServing: snapshot.serving,
    skipped: plan.skipped || [],
  };
}

// 快照说能服务、探测说不能 ＝ 两侧判据分歧。探测是实测，结论以它为准；
// 这里只让分歧可观测，不静默吞掉（契约要求：分歧必须告警）。
function capabilityDivergences(snapshotServing, classified) {
  if (!Array.isArray(snapshotServing) || snapshotServing.length === 0) return [];
  return snapshotServing.filter((id) => classified?.[id] && classified[id].status !== "serving");
}

function logProbePlan(name, id, plan, classified) {
  const probed = Object.keys(classified || {}).length;
  const parts = [`source=${plan.source}`, `probed=${probed}`];
  if (plan.skipped.length > 0) parts.push(`skipped=${plan.skipped.length}`);
  const diverged = capabilityDivergences(plan.snapshotServing, classified);
  if (diverged.length > 0) parts.push(`diverged=${diverged.length}`);
  console.log(`[llm-providers] probe plan "${name}" (${id}): ${parts.join(" ")}`);
  if (diverged.length > 0) {
    console.warn(
      `[llm-providers] capability/probe divergence "${name}" (${id}): ` +
        `${diverged.join(",")} — snapshot called them serving, probe did not; probe wins`
    );
  }
}

// Upgrade every roster entry still carrying a conservative default to its
// family value (the resolver's rule, applied as a write). Returns copies, so a
// roster that came from a module constant (the baked VOLCES_MODELS) is never
// mutated in place, plus the ids it touched so the caller can report them.
function reconcileRoster(roster) {
  const upgraded = [];
  const out = roster.map((entry) => {
    const patch = reconcileModelMeta(entry);
    if (!patch) return entry;
    upgraded.push(entry.id);
    return { ...entry, ...patch };
  });
  return { roster: out, upgraded };
}

// Reconcile a provider's roster against its own gateway (design D1–D8).
// Classification happens BEFORE the write lock; inside it: merge `serving`
// ids (append + family metadata), reconcile metadata of entries already present
// that still carry a conservative default, re-order by family rank, persist the
// `discovery` status map. The reserved env route ("volces") runs the same
// pipeline targeting its override (add-editable-llm-route): the built-in lane
// reconciles against gateway drift through the same operator action, no image
// rebuild.
export async function syncProvider(id, { fetchImpl = global.fetch, reload } = {}) {
  if (syncInFlight) throw new ProviderError("busy", "a model sync is already running");
  if (RESERVED_IDS.has(id)) {
    const apiKey = process.env.LLM_API_KEY?.trim();
    if (!apiKey) throw new ProviderError("invalid", "reserved route has no API key configured");
    syncInFlight = true;
    let classified;
    let plan;
    let baseUrl;
    try {
      const dshProfile = await import("./dsh-profile.js");
      baseUrl = (await dshProfile.effectiveVolcesRoute()).baseURL;
      plan = await planSyncProbeSet(baseUrl, apiKey, { fetchImpl });
      classified = await classifyModels(baseUrl, apiKey, plan.ids, { fetchImpl });
      logProbePlan("Volces", id, plan, classified);
    } finally {
      syncInFlight = false;
    }

    const probedAt = new Date().toISOString();
    return tryWithWriteLock(async () => {
      const dshProfile = await import("./dsh-profile.js");
      const starting = [...(await dshProfile.effectiveVolcesRoute()).models];
      const { roster, upgraded } = reconcileRoster(starting);
      const existing = new Set(roster.map((m) => m.id));
      const added = [];
      for (const [mid, r] of Object.entries(classified)) {
        if (r.status !== "serving" || existing.has(mid)) continue;
        const meta = modelFamilyMeta(mid);
        roster.push({ id: mid, name: prettifyModelId(mid), ...meta });
        added.push(mid);
      }
      roster.sort((a, b) => compareModelIds(a.id, b.id));
      const discovery = toDiscoveryMap(classified, probedAt);
      setVolcesOverride({ models: roster, discovery });
      if (reload) await reload();
      console.log(
        `[llm-providers] sync "Volces" (volces): ${added.length} added, ${upgraded.length} metadata upgraded, override roster ${roster.length}`
      );
      return { statuses: discovery, added, upgraded, rosterSize: roster.length };
    });
  }

  const record = getProviderRecord(id);
  if (!record) throw new ProviderError("not_found", `provider ${id} not found`);
  const keyless = record.auth === "none";
  if (!record.apiKey && !keyless) throw new ProviderError("invalid", "provider has no API key configured");

  syncInFlight = true;
  let classified;
  let plan;
  try {
    plan = await planSyncProbeSet(record.baseUrl, record.apiKey, { fetchImpl, auth: record.auth });
    classified = await classifyModels(record.baseUrl, record.apiKey, plan.ids, { fetchImpl, auth: record.auth });
    logProbePlan(record.name, id, plan, classified);
  } finally {
    syncInFlight = false;
  }

  const probedAt = new Date().toISOString();
  return tryWithWriteLock(async () => {
    const doc = readProvidersDoc();
    const idx = doc.providers.findIndex((p) => p.id === id);
    if (idx < 0) throw new ProviderError("not_found", `provider ${id} not found`);
    const current = doc.providers[idx];
    const { roster, upgraded } = reconcileRoster(current.models || []);
    const existing = new Set(roster.map((m) => m.id));
    const added = [];
    for (const [mid, r] of Object.entries(classified)) {
      if (r.status !== "serving" || existing.has(mid)) continue;
      const meta = modelFamilyMeta(mid);
      roster.push({ id: mid, name: prettifyModelId(mid), ...meta });
      added.push(mid);
    }
    // Order is policy, policy lives in code (D5): family rank, then id.
    roster.sort((a, b) => compareModelIds(a.id, b.id));
    const discovery = toDiscoveryMap(classified, probedAt);
    doc.providers[idx] = { ...current, models: roster, discovery, updatedAt: probedAt };
    writeJsonAtomic(STORE_PATH, doc);
    if (reload) await reload();
    console.log(
      `[llm-providers] sync "${current.name}" (${id}): ${added.length} added, ${upgraded.length} metadata upgraded, roster ${roster.length}`
    );
    return { statuses: discovery, added, upgraded, rosterSize: roster.length };
  });
}

function toDiscoveryMap(classified, probedAt) {
  const map = {};
  for (const [id, r] of Object.entries(classified)) {
    map[id] = {
      status: r.status,
      ...(r.error ? { error: r.error } : {}),
      ...(probedAt ? { probedAt } : {}),
    };
  }
  return map;
}
